package com.gryphlabs.phoenix.api.entity;
import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import java.time.Instant;
@Entity @Table(name="email_change_tokens", indexes=@Index(name="ix_email_change_token_hash", columnList="token_hash", unique=true)) @Getter @Setter @NoArgsConstructor
public class EmailChangeToken { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="token_hash",nullable=false,unique=true,length=64) private String tokenHash; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @Column(nullable=false) private String proposedEmail; @Column(nullable=false) private Instant expiresAt; @Column(nullable=false) private boolean consumed; }
